		"variant":                  "snapshot-covers-the-change",
		"snapshot_index":           snapIdx,
		"snapshot_config_servers":  len(snapConf.Servers),
		"config_in_force_servers":  len(forceConf.Configuration().Servers),
		"recovered_config_servers": len(recovered.Servers),
		"recovered_matches_force":  len(recovered.Servers) == len(forceConf.Configuration().Servers),
		"gap_absent":               len(recovered.Servers) == len(forceConf.Configuration().Servers),
	})
}

// TestAssurance_TimeoutNowRepeatFromRemovedNode measures whether the transfer
// trigger can be repeated from the same non-member sender, producing leadership
// churn round after round.
func TestAssurance_TimeoutNowRepeatFromRemovedNode(t *testing.T) {
	conf := inmemConfig(t)
	conf.ElectionTimeout = 200 * time.Millisecond
	conf.HeartbeatTimeout = 100 * time.Millisecond
	conf.LeaderLeaseTimeout = 100 * time.Millisecond

	c := MakeCluster(3, t, conf)
	defer func() {
		defer func() { _ = recover() }()
		c.Close()
	}()

	var leader *Raft
	if !caPoll(func() bool {
		leader = caFindLeader(c.rafts...)
		return leader != nil
	}, 20*time.Second) {
		t.Fatalf("no leader")
	}
	if err := leader.Apply([]byte("warm"), 5*time.Second).Error(); err != nil {
		t.Fatalf("apply: %v", err)
	}

	// Pick a node to remove; it stays transport-reachable.
	removedIdx := -1
	for i, r := range c.rafts {
		if r != leader {
			removedIdx = i
			break
		}
	}
	removed := c.rafts[removedIdx]
	if err := leader.RemoveServer(removed.localID, 0, 0).Error(); err != nil {
		t.Fatalf("RemoveServer: %v", err)
	}
	caPoll(func() bool { return !inConfiguration(removed.getLatestConfiguration(), removed.localID) }, 10*time.Second)

	rounds := 3
	changedRounds := 0
	settled := 0
	terms := []uint64{}
	for round := 0; round < rounds; round++ {
		// Pick a surviving follower that is not the current leader.
		cur := caFindLeader(c.rafts...)
		var target *Raft
		for _, r := range c.rafts {
			if r != removed && r != cur {
				target = r
				break
			}
		}
		if target == nil {
			break
		}
		beforeLeader := cur
		beforeTerm := target.getCurrentTerm()
		// Send from the removed node's own transport, which already routes to
		// every peer in the cluster.
		own := removed.trans.(*InmemTransport)
		err := own.TimeoutNow(target.localID, target.localAddr, &TimeoutNowRequest{
			RPCHeader: RPCHeader{ProtocolVersion: removed.protocolVersion, ID: []byte(removed.localID),
				Addr: own.EncodePeer(removed.localID, removed.localAddr)},
		}, &TimeoutNowResponse{})

		_ = err
		caPoll(func() bool { return caFindLeader(c.rafts...) != nil && caFindLeader(c.rafts...) != beforeLeader }, 5*time.Second)
		after := caFindLeader(c.rafts...)
		if after != nil && after != beforeLeader {
			changedRounds++
		}
		if after != nil {
			settled++
			terms = append(terms, target.getCurrentTerm())
		}
		_ = beforeTerm
	}

	caEmit(t, map[string]interface{}{
		"event":                       "timeoutnow_repeat_from_removed",
		"variant":                     "three-voter-one-removed",
		"rounds_requested":            rounds,
		"rounds_with_leadership_change": changedRounds,
		"rounds_with_a_stable_leader": settled,
		"churn_persisted":             changedRounds >= 2,
		"terms_after_each_round":      terms,
	})
}

// TestAssurance_LiveClusterEmptyConfigRestart probes the live-cluster effect of
// the empty configuration a RestoreCommittedLogs restart leaves behind when the
// restarted node shares a cluster with the legitimate leader: whether the
// legitimate leader's heartbeats restore the node's leader and feed it entries,
// and whether an outsider that is in no configuration can still use the node to
// pull the term up and cost the cluster its serving leader.
func TestAssurance_LiveClusterEmptyConfigRestart(t *testing.T) {
	conf := caConf(t)
	conf.HeartbeatTimeout = 200 * time.Millisecond
	conf.ElectionTimeout = 200 * time.Millisecond
	conf.LeaderLeaseTimeout = 200 * time.Millisecond

	c := MakeClusterCustom(t, &MakeClusterOpts{Peers: 3, Bootstrap: true, Conf: conf, CommitTrackingLogs: true})
	defer func() {
		defer func() { _ = recover() }()
		c.Close()
	}()

	var leader *Raft
	if !caPoll(func() bool {
		leader = caFindLeader(c.rafts...)
		return leader != nil
	}, 20*time.Second) {
		t.Fatalf("no leader")
	}
	for i := 0; i < 8; i++ {
		if err := leader.Apply([]byte(fmt.Sprintf("pre-%d", i)), 5*time.Second).Error(); err != nil {
			t.Fatalf("apply: %v", err)
		}
	}

	idx := -1
	for i, r := range c.rafts {
		if r != leader {
			idx = i
			break
		}
	}
	if idx < 0 {
		t.Fatalf("no follower")
	}
	old := c.rafts[idx]
	confInForce := leader.getLatestConfiguration()
	staged := mustCommitIndex(t, old)
	lastBefore, _ := old.logs.LastIndex()

	caEmit(t, map[string]interface{}{
		"event":                         "live_cluster_setup",
		"variant":                       "three-voter-restart-one-follower",
		"config_in_force":               caServers(confInForce),
		"config_in_force_voters":        len(caVoters(confInForce)),
		"leader_id":                     string(leader.localID),
		"restarted_node_id":             string(old.localID),
		"restarted_staged_commit_index": staged,
		"restarted_last_log_index":      lastBefore,
	})

	if err := old.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown follower: %v", err)
	}
	_, trans2 := NewInmemTransport(old.localAddr)
	cfg2 := old.config()
	restarted, err := NewRaft(&cfg2, old.fsm, old.logs, old.stable, old.snapshots, trans2)
	if err != nil {
		t.Fatalf("restart follower: %v", err)
	}
	c.rafts[idx] = restarted
	c.trans[idx] = trans2
	c.FullyConnect()

	live := restarted.getLatestConfiguration()
	_, leaderAtStart := restarted.LeaderWithID()
	caEmit(t, map[string]interface{}{
		"event":                          "live_cluster_restart_state",
		"variant":                        "three-voter-restart-one-follower",
		"live_config_after_restart":      caServers(live),
		"live_config_len_after_restart":  len(live.Servers),
		"restarted_state":                restarted.State().String(),
		"restarted_leader_after_restart": string(leaderAtStart),
		"restarted_term_after_restart":   restarted.getCurrentTerm(),
		"leader_in_recovered_config":     inConfiguration(live, leader.localID),
	})

	converged := caPoll(func() bool {
		_, id := restarted.LeaderWithID()
		return id == leader.localID
	}, 15*time.Second)

	payload := []byte("live-cluster-command")
	applyErr := leader.Apply(payload, 5*time.Second).Error()
	received := false
	if ok := caPoll(func() bool {
		has, _ := caHoldsPayload(restarted, payload)
		received = has
		return has
	}, 10*time.Second); !ok {
		received = false
	}

	lastAfter, _ := restarted.logs.LastIndex()
	_, leaderAfter := restarted.LeaderWithID()
	caEmit(t, map[string]interface{}{
		"event":                                    "live_cluster_heartbeat_convergence",
		"variant":                                  "three-voter-restart-one-follower",
		"leader_converged_to_serving_leader":       converged,
		"restarted_leader_after_contact":           string(leaderAfter),
		"restarted_leader_matches_serving_leader":  leaderAfter == leader.localID,
		"restarted_live_config_len_after_contact":  len(restarted.getLatestConfiguration().Servers),
		"restarted_state_after_contact":            restarted.State().String(),
		"restarted_campaigned_on_its_own":          restarted.State() != Follower,
		"leader_apply_error":                       fmt.Sprint(applyErr),
		"restarted_received_new_command":           received,
		"restarted_last_log_index_after":           lastAfter,
		"restarted_last_log_index_before":          lastBefore,
	})

	peerAddr, peerTrans := NewInmemTransport("")
	defer peerTrans.Close()
	own := restarted.trans.(*InmemTransport)
	own.Connect(peerAddr, peerTrans)
	peerTrans.Connect(restarted.localAddr, own)

	outsider := ServerID("outsider-not-in-config")
	encoded := peerTrans.EncodePeer(outsider, peerAddr)
	termBefore := restarted.getCurrentTerm()
	aResp := &AppendEntriesResponse{}
	aErr := peerTrans.AppendEntries(outsider, restarted.localAddr, &AppendEntriesRequest{
		RPCHeader:         RPCHeader{ProtocolVersion: restarted.config().ProtocolVersion, ID: []byte(outsider), Addr: encoded},
		Term:              termBefore + 5,
		Leader:            encoded,
		PrevLogEntry:      0,
		PrevLogTerm:       0,
		LeaderCommitIndex: 0,
	}, aResp)
	_, leaderAfterOutsider := restarted.LeaderWithID()
	steppedDown := caPoll(func() bool { return leader.State() != Leader }, 5*time.Second)
	newLeader := caFindLeader(c.rafts...)

	caEmit(t, map[string]interface{}{
		"event":                                       "live_cluster_outsider_contact",
		"variant":                                     "three-voter-restart-one-follower",
		"append_entries_error":                        fmt.Sprint(aErr),
		"append_entries_success":                      aResp.Success,
		"restarted_term_after_outsider":               restarted.getCurrentTerm(),
		"restarted_leader_after_outsider":             string(leaderAfterOutsider),
		"outsider_became_leader_of_restarted_node":    leaderAfterOutsider == outsider,
		"serving_leader_stepped_down":                 steppedDown,
		"serving_leader_state_after":                  leader.State().String(),
		"cluster_leader_present_after":                newLeader != nil,
		"restarted_live_config_len_final":             len(restarted.getLatestConfiguration().Servers),
	})
}

